INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ORTH_ALEXANDRA_FEODOROVNA_FARLEY','ENT_ORTH_ALEXANDRA_FEODOROVNA','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Her sister Alexandra married the Russian tsar, so that Elizabeth ("Ella" to her family) became part of the Russian royal family. She married the Grand Duke Sergius, the governor of Moscow. She later converted from Protestantism to Orthodoxy of her own free will and was received by chrismation on Lazarus Saturday in 1891. Her pious spirit could not hide in a life of privilege but worked tirelessly to serve the sick in hospitals.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_CYRIL_METHODIUS_FARLEY','ENT_ORTH_CYRIL_METHODIUS','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Cyril and Methodius, Equals-to-the-Apostles Constantine and Methodius were brothers of great wealth, natives of Thessalonica, in which border city Greeks and Slavs mingled together. Constantine had a career in the imperial court but forsook it to live as a monk. His older brother Methodius had a career in the army, which he also forsook for monastic discipline. The two retired to a monastery in Mount Olympus in 850.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_ELIZABETH_FEODOROVNA_FARLEY','ENT_ORTH_ELIZABETH_FEODOROVNA','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','John was born to righteous Zachariah and Elizabeth, God having made the barren woman fertile in her old age. While yet in the womb, John leaped for joy as the greeting of the Mother of God reached the ears of his mother, Elizabeth. Named John by his father in obedience to the Archangel Gabriel''s word, he came in the spirit and power of Elijah to restore righteousness to Israel through the preaching of repentance.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_IGNATIUS_BRIANCHANINOV_FARLEY','ENT_ORTH_IGNATIUS_BRIANCHANINOV','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Ignatius the God-Bearer St. Ignatius''s principal feast is December 20-today is the feast of the translation of his relics. Ignatius, Bishop of Antioch, was arrested in his old age and taken to Rome, where he was thrown to the beasts and martyred in the year 107. His companions collected his bones and returned to Antioch, where they buried them, laying them in a chest as a great treasure.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_JOHN_KRONSTADT_FARLEY','ENT_ORTH_JOHN_KRONSTADT','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','John of Kronstadt, the saint cried out, "Matrona, come here!" adding that she would be his heir and a pillar of Russia. Illness struck the young girl again at the age of seventeen, so that she was ever after unable to walk. She remained steadfast and patient throughout her life, quietly praying, receiving all the visitors who came to her, and foretelling the terrible fortunes which would befall her country at the hands of the Bolsheviks.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_JUSTIN_POPOVIC_FARLEY','ENT_ORTH_JUSTIN_POPOVIC','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','JANUARY 14 The Holy Martyrs of Mount Sinai and Raithu Before the Emperor Justinian built the fortress-like monastery at its present site on Mount Sinai, many monks lived there in the desert, scattered in the wilderness. A Saracen chief was encamped in the area at that time, near the place where the monks gathered for Sunday liturgy.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MARIA_SKOBTSOVA_FARLEY','ENT_ORTH_MARIA_SKOBTSOVA','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Mother Maria Skobtsova of Paris was glorified by the ecumenical patriarchate in 2004. JULY 21 Holy Prophet Ezekiel Ezekiel was the son of Buzi and a priest in the temple. He was taken captive from Jerusalem to Babylon in the reign of King Jehoiachin in 597 BC. He formed the center of a group of Jewish exiles by the River Chebar.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MATRONA_MOSCOW_FARLEY','ENT_ORTH_MATRONA_MOSCOW','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','APRIL 19 Blessed Matrona of Moscow Matrona was born in 1881 to a poor family in the village of ­Sebino- Epifaniskaya, in the Tula region. She was blind from birth, having no pupils in her eyes. From the age of about six, God gave the child extraordinary gifts of prophecy and healing. When she was taken to see the then-famous Fr. John of Kronstadt, the saint cried out, "Matrona, come here!" adding that she would be his heir and a pillar of Russia.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MENAS_FARLEY','ENT_ORTH_MENAS','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','N OVE MBER 11 Holy Great Martyr Menas Menas was an Egyptian and served in the Roman Army. When persecution began against army officers, he left the army and retired to a place of refuge with other Christians. When the persecution broke out against the general Christian populace in 303, he emerged from his solitary refuge and returned to the city of Cotyaeus.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_NECTARIOS_AEGINA_FARLEY','ENT_ORTH_NECTARIOS_AEGINA','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','He therefore found an abandoned and tumbledown monastery on the island of Aegina, which he repaired with his own hands, eventually founding a community of nuns there. Nectarius''s health began to fail, and in 1920 he was admitted to a state hospital for the poor in Athens. The admitting intern would hardly believe that the old man in black robes was a bishop.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_NICHOLAS_II_FARLEY','ENT_ORTH_NICHOLAS_II','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Seraphim''s many visitors was Nicholas Motovilov. In a visit with the saint, Nicholas saw him shine with the uncreated light of God. St. Seraphim was a man filled with God and the joy of His Kingdom. Year round, he would greet each visitor with the salutation, "Christ is risen, my joy!" He taught that the goal of the Christian life was the acquisition of the Holy Spirit, and that if one acquired the Spirit of peace, thousands would be saved by example.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_ROYAL_MARTYRS_FARLEY','ENT_ORTH_ROYAL_MARTYRS','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','His mother, an enthusiastic Christian and devotee of relics, obtained the relics of the Forty Martyrs of Sebaste and prepared to house them in a chapel built for them on her estate in Annesi. Young Gregory, not yet fervent, was bored by the all-night vigil of psalm-singing and at length, annoyed and angry at it all, left the garden chapel and fell asleep elsewhere. There he dreamed of the Forty Martyrs and was converted.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_SERAPHIM_FARLEY','ENT_ORTH_SERAPHIM','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Our Holy Father Seraphim of Sarov Born in Kursk, Russia, in 1759 with the name Prokhor, the future saint was a son of devout Christian parents of the merchant class. At the age of eighteen, he entered a monastery in Sarov, devoting himself to saying the Jesus Prayer and continuing in humble service in the monastery, baking bread and working in the woodwork shop. After four years the young man fell quite ill and was near death.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_SIMEON_STYLITES_FARLEY','ENT_ORTH_SIMEON_STYLITES','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','As a young man, Simeon was greatly influenced by the example of St. Simeon the Stylite, who had died about a hundred years earlier and whose relics were in Antioch (his feast day is September 1). Inspired by his elder namesake, the younger Simeon also built a pillar outside Antioch and adopted the asceticism of living there as a stylite.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_THREE_HIERARCHS_FARLEY','ENT_ORTH_THREE_HIERARCHS','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','JANUARY 30 The Three Holy Hierarchs This feast was instituted in the eleventh century. At that time there was a quarrel among the people about which of these three hierarchs was the greatest-St. Basil the Great, St. Gregory the Theologian, or St. John Chrysostom. The quarrel was resolved by a dream divinely sent to Bishop John of Euchaita.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_CHRYSOSTOM_FARLEY','ENT_ORTH_CHRYSOSTOM','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','John Chrysostom St. John''s feast day is November 13. This day commemorates his relics being brought with honor from Armenia to the capital city of Constantinople. St. John died in exile far away in the village of Comana in Armenia, having been banished there by the spiteful Empress Eudoxia for his fearless stand for righteousness and his denunciation of the empress''s sins.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_MARY_EGYPT_FARLEY','ENT_ORTH_MARY_EGYPT','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','Mary of Egypt and the prayer for the Great Blessing of Water used at Theophany. He was a great lover of spiritual wisdom. MARCH 12 Our Holy Father Theophanes the Confessor Theophanes was born to a wealthy family in Constantinople in 759. He was betrothed at the age of twelve to a rich young lady. At the age of twenty, when the time of their marriage drew near, he persuaded his bride that they should live together as brother and sister.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_PANTELEIMON_FARLEY','ENT_ORTH_PANTELEIMON','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','JULY 27 Holy Great Martyr Panteleimon Panteleimon was born to a pagan father and a Christian mother, Euboulia, and was given the name Pantoleon. His parents placed him under a well-known physician for his education. He became a physician in turn and won great fame for his medical skill. He was converted to Christ by Hermolaus, a presbyter who was hiding in Nicomedia to escape persecution.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ORTH_THEODORE_FARLEY','ENT_ORTH_THEODORE','SRC_SYNAXARION','A Daily Calendar of Saints (Farley)','A Daily Calendar of Saints (Farley)','FEBRUARY 8 Holy Great Martyr Theodore Stratelates ("the General") Theodore was a general under Licentius and a governor whose capital was Heraklea in Pontus. For his faith in Christ, he scorned military and worldly glory and advancement and suffered as a martyr. His sufferings were particularly severe: he was flogged seven hundred times on his back, fifty times on his stomach, and then struck on the back of the neck with a lead-tipped scourge.','Lawrence Farley',2018,'None',NULL,'primary-verbatim',NULL,true,'Located by name in an Orthodox synaxarion; brief flagged excerpt; verify the commemoration.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
